use std::fs::{self, File, OpenOptions};
use std::io::{self, BufWriter, Write};
use std::path::{Path, PathBuf};
use std::sync::Mutex;

#[path = "/app/slipcards/cap.rs"]
mod cap;

static BAG: Mutex<Vec<u8>> = Mutex::new(Vec::new());
static SLOT: Mutex<Option<CardWriter>> = Mutex::new(None);

pub struct CardWriter {
    out: BufWriter<File>,
    tmp: PathBuf,
    dest: PathBuf,
}

impl Write for CardWriter {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        self.out.write(buf)
    }

    fn flush(&mut self) -> io::Result<()> {
        self.out.flush()
    }
}

impl Drop for CardWriter {
    fn drop(&mut self) {
        let _ = fs::remove_file(&self.tmp);
    }
}

#[allow(dead_code)]
pub fn stash(b: Vec<u8>) {
    *BAG.lock().unwrap() = b;
}

pub fn op_b(p: &str) -> CardWriter {
    let dest = PathBuf::from(p);
    let parent = dest.parent().expect("destination has no parent");
    let name = dest.file_name().and_then(|v| v.to_str()).unwrap_or("card");
    let tmp = parent.join(format!(".{}.finspool.{}.tmp", name, std::process::id()));
    let _ = fs::remove_file(&tmp);
    let file = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&tmp)
        .expect("cannot create temporary card");
    CardWriter {
        out: BufWriter::with_capacity(cap::ROOM, file),
        tmp,
        dest,
    }
}

pub fn park(s: CardWriter) {
    *SLOT.lock().unwrap() = Some(s);
}

pub fn release() -> bool {
    let extra = BAG.lock().unwrap().split_off(0);
    let mut slot = SLOT.lock().unwrap();
    let mut card = match slot.take() {
        Some(v) => v,
        None => return false,
    };
    let result = (|| -> io::Result<()> {
        if !extra.is_empty() {
            card.write_all(&extra)?;
        }
        crate::seal::drip(&mut card);
        card.flush()?;
        card.out.get_ref().sync_all()?;
        fs::rename(&card.tmp, &card.dest)?;
        if let Some(parent) = card.dest.parent() {
            File::open(parent)?.sync_all()?;
        }
        Ok(())
    })();
    result.is_ok()
}

#[allow(dead_code)]
fn _path_type(_: &Path) {}
EOF
