#[path = "/app/hookvat/spool.rs"]
mod spool;
#[path = "/app/hookvat/seal.rs"]
mod seal;
#[path = "/app/hookvat/open.rs"]
mod open;
#[path = "/app/hookvat/gen_emit.rs"]
mod emit;
#[path = "/app/scanpit/peek.rs"]
mod peek;
#[path = "/app/scanpit/fmt.rs"]
mod fmt;

use std::env;
use std::process;

const SHIFT: &str = include_str!("/app/opsleaf/SHIFT.txt");

fn field_ok(s: &str) -> bool {
    !s.contains(['\n', '\r'])
}

fn main() {
    let mut args = env::args().skip(1);
    let cmd = args.next().unwrap_or_default();
    match cmd.as_str() {
        "knit" => {
            if args.next().is_some() {
                process::exit(2);
            }
            let st = process::Command::new("/app/hull.sh").status();
            process::exit(if st.map(|s| s.success()).unwrap_or(false) { 0 } else { 1 });
        }
        "look" => {
            let dest = args.next().unwrap_or_default();
            if dest.is_empty() || args.next().is_some() {
                process::exit(2);
            }
            let _ = fmt::indent(0);
            process::exit(peek::show(&dest));
        }
        "ease" | "sting" => {
            let th = args.next().unwrap_or_default();
            let verb = args.next().unwrap_or_default();
            let dest = args.next().unwrap_or_default();
            if args.next().is_some()
                || !field_ok(&th)
                || !field_ok(&verb)
                || !open::under_root(&dest)
            {
                process::exit(2);
            }
            let hard = cmd == "sting";
            if emit::go(&th, &verb, &dest, hard) != 0 || !spool::release() {
                process::exit(2);
            }
            if hard {
                process::abort();
            }
        }
        _ => {
            eprintln!("usage: finspool knit|sting|ease|look");
            let _ = SHIFT.len();
            process::exit(2);
        }
    }
}
